"""History scanning and reconciliation with operations generated by replay."""

from __future__ import annotations

from typing import TYPE_CHECKING

from duron.errors import HistoryMismatchError, InterruptedEffectError

if TYPE_CHECKING:
    import asyncio
    from collections.abc import AsyncIterator, Awaitable, Callable

    from duron._history.entries import Entry
    from duron._runtime.loop import WaitSet
    from duron._runtime.state import Operation


class ReplayState:
    """Operations generated ahead of the replay frontier, before live execution."""

    __slots__ = ("pending",)

    def __init__(self) -> None:
        self.pending: dict[str, Entry] = {}

    async def resume(
        self,
        history: AsyncIterator[tuple[int, Entry]],
        advance: Callable[[int], Awaitable[WaitSet | None]],
        apply: Callable[[int, Entry], bool],
        main: asyncio.Task[object],
        operations: dict[str, Operation],
    ) -> bool:
        ws: WaitSet | None = None
        async for offset, entry in history:
            if entry["type"] == "promise.create" and entry["source"] == "effect":
                continue
            ts = entry["ts"]
            while ws and ws.timer and ws.timer < ts:
                ws = await advance(ws.timer)

            ws = await advance(ts)
            self._raise_history_error(main)
            if entry["source"] == "task":
                expected = self.pending.pop(entry["id"], None)
                if expected is None:
                    msg = "Extra messages found in log"
                    raise HistoryMismatchError(msg, actual=entry["id"])
                validate_recorded_entry(expected, entry)
            # A cancelled waiter can still have a committed operation. Matching
            # its generated entry above is sufficient even if apply has no waiter.
            _ = apply(offset, entry)
            ws = await advance(ts)
            self._raise_history_error(main)

        for id_, operation in operations.items():
            if operation.effect is not None and operation.committed is not None:
                raise InterruptedEffectError(id_)

        return main.done() and not self.pending

    @staticmethod
    def _raise_history_error(main: asyncio.Task[object]) -> None:
        if main.done() and not main.cancelled():
            error = main.exception()
            if isinstance(error, HistoryMismatchError):
                raise error


def effect_identity(entry: Entry) -> tuple[object, ...] | None:
    if entry["type"] != "promise.create":
        return None
    ref = entry.get("ref")
    if ref is None:
        return None
    if "args" in entry and "kwargs" in entry:
        return (ref["name"], entry["args"], entry["kwargs"])
    return (ref["name"],)


def validate_recorded_entry(expected: Entry, persisted: Entry) -> None:
    persisted_type = persisted["type"]
    if persisted_type != expected["type"]:
        msg = (
            f"operation kind mismatch at id {expected['id']!r}: persisted "
            f"{persisted_type!r}, requested {expected['type']!r}"
        )
        raise HistoryMismatchError(
            msg, expected=persisted_type, actual=expected["type"]
        )
    requested = effect_identity(expected)
    persisted_identity = effect_identity(persisted)
    if persisted_identity != requested:
        msg = (
            f"effect identity mismatch: persisted {persisted_identity!r}, "
            f"requested {requested!r}"
        )
        raise HistoryMismatchError(msg, expected=persisted_identity, actual=requested)
